// 英単語の意味を日本語の声で読むときの、漢字の読み（画面の文字は変えず、読み上げだけに使う）。
// 端末の声は漢字の読みを自分で決めるので、意味のように前後のない短い語では読み違えやすい（一歩＝いちほ、宝物＝ほうもつ、
// 端＝はじ など）。そこで英単語の意味の読み上げ文にある漢字のかたまり（前後の数字を含む）を全部、文の中での読みに決めて、
// かなで声に渡す。読みは2つの辞書（IPADIC・UniDic）の候補を出してから、辞書が一致した所も含めて全件を人が読んで決めた（2026-11-19）。
// キーは英単語の id（password などが秘密情報の検査に取り違えられないよう、引用符で囲む）。値は「漢字のかたまり=読み」を、読み上げ文に出てくる順に「,」でつないだもの。
// 読み上げ文は cardJapaneseSpeechTexts が意味から作る文（（よみ）の台帳と japanese-speech-readings.js を当てたあと）。
// 意味を書き直すと、かたまりが台帳と合わなくなり tests/meaning-speech-kana.test.mjs が止める。読み直して台帳を直す。
